function UIJackpotDungoenMainDialog:OnShow()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        while not self._isCanShow do
            coroutine.yield(Yielders.EndOfFrame)
        end
        if self._isEnd then
            GameUtils.SecondConfirm(localize("活动已结束"), function()
                UIModule.BackDialog()
            end, function()
                UIModule.BackDialog()
            end)
            return
        end
        local CriWareUtils = import('Game.Entry.CriWareUtilsFix')
        CriWareUtils.PlaySe("Audio/Halloween", "ui_halloween_nangua")

        local t = comp:GetQuestInfo()
        --第一次
        if checkNumber(t.newUnlockPoolId) == 0 then
            local _t = HalloweenUtils.GetAllRewardPool(self._activityId)
            local vo = HalloweenUtils.GetHalloweenRewardPoolVo(_t[1])
            if checkNumber(vo.plotId) > 0 then
                self:PlayPlot(vo.plotId, function()
                    comp:ActivityGashaponQuestPlotReq(vo.plotId, function()
                    end)
                end)
            end
        end
    end))
    return coWait
end

