    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        local CriWareUtils = import('Game.Entry.CriWareUtilsFix')
        CriWareUtils.RemoveCueSheet("Audio/Halloween")
    end))
    return coWait
end


--播放剧情
function UIJackpotDungoenMainDialog:PlayPlot(id, endCb)
    if self.isPlayPlot then
        return
    end
    self.isPlayPlot = true
    local plotVo = QuestConfMgr:GetInstance():GetQuestVoById(id)

    local plotIds = CfUtils.Split(plotVo.plotId)
    if not plotIds then
        GameUtils.Toast(localize("该关卡没有剧情参数"))
        return 
    end

    self.curPlotIndex = 1
    self:PlayPloting(plotIds, endCb)
end

function UIJackpotDungoenMainDialog:PlayPloting(plotIds, endCb)
    ChapterUtils.ProcessChapter(checkNumber(plotIds[self.curPlotIndex]), function(go)
        self.controller.gameObject.transform.localPosition = Vector3(9999, 9999, 9999)
        CS.UINavigationBarRoot.Instance:SetActive(false)
        self._plotGo = go
    end, function()
        --所有的播完结束
        if self.curPlotIndex >= table.count(plotIds) then
            if endCb then
                endCb()
            end

            self.controller.gameObject.transform.localPosition = Vector3(0, 0, 0)
            CS.UINavigationBarRoot.Instance:SetActive(true)
            KTool.SafeDelete(self._plotGo)
            self.isPlayPlot = false

            local CriWareUtils = import('Game.Entry.CriWareUtilsFix')
            CriWareUtils.PlayMusicById("bgm_instance_halloween")
        else
            self.curPlotIndex = self.curPlotIndex + 1
            KTool.SafeDelete(self._plotGo)
            self:PlayPloting(plotIds, endCb)
        end
    end)
end

function UIJackpotDungoenMainDialog:FillSelf()
    self:FillTime()

    --SetButtonAction(self.BtnReview, Bind(self, self.OnBtnReview))
    CfUtils.SetActive(self.BtnReview, false)
    SetButtonAction(self.BtnGachapon, Bind(self, self.OnBtnGachapon))
    SetButtonAction(self.BtnTips, Bind(self, self.OnBtnTips))
    SetButtonAction(self.BtnBattle, Bind(self, self.OnBtnBattle))
    SetButtonAction(self.BtnExchange, Bind(self, self.OnBtnExchange))

    CfUtils.FillText(self.TxtNumber, GoodsUtils.GetThingNo(self._activityVo.drawConsume))
    local redGo = GameUtils.GetRedPointGo(self.BtnExchange)
    if redGo then
        CfUtils.SetActive(redGo, GoodsUtils.GetThingNo(self._activityVo.drawConsume) >= checkNumber(self._activityVo.redPoint))
    end
end

