function UIJackpotDungoenMainDialog:FillTime()
    local t = ActivityMgr:GetInstance():GetActivityData()
    if not t then
        return
    end

    local data = nil
    local uuId = HalloweenUtils.GetUuid()
    for k, v in pairs(t) do
        if checkInt(v.type) == ActivityConstants.ActivityType.HalloweenQuest and checkNumber(v.id) == checkNumber(uuId) then
            data = v
            break
        end
    end

    if data then
        CfUtils.FillText(self.TxtTime, ActivityUtils.ConventActivityDurationTime(data.startTime, data.endTime))
    end
end

function UIJackpotDungoenMainDialog:OnInitialize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        local CriWareUtils = import('Game.Entry.CriWareUtilsFix')
        CriWareUtils.PlayMusicById("bgm_instance_halloween")

        local argument = self.controller.Argument.parameters
        if argument then
            self._activityUuid = checkNumber(argument.activityUuid)  
        end
        if checkNumber(self._activityUuid) <= 0 then
            return
        end
        comp:SetUuid(self._activityUuid)

        local isOpen = HalloweenUtils.IsOpen()
        if not isOpen then
            self._isCanShow = true
            self._isEnd = true
        else
            GameUtils.Request(Interfaces.ActivityGashaponQuestHome, {activityUuid = self._activityUuid}, function(request, response)
                if checkNumber(response.errCode) ~= 0 then
                    self._isCanShow = true
                    self._isEnd = true
                    return
                end
                local jsonData = response.data
        
                local comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.HalloweenQuestComponent)
                comp:Initial(self._activityUuid, jsonData)
        
                local activityId = jsonData.gashaponConf.id
                self._activityId = activityId
    
                CfUtils.RefreshTopGoods(HalloweenUtils.GetShowGoods(self._activityId))
    
                self._activityVo = HalloweenUtils.GetHalloweenPlanVo(self._activityId)
                if not self._activityVo then 
                    return
                end
        
                self:FillSelf()
    
                self._isCanShow = true
            end)
        end
    end))
    return coWait
end

function UIJackpotDungoenMainDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

return UIJackpotDungoenMainDialog
